import SwiftUI

struct Errand: Identifiable {
    let id = UUID()
    let title: String
    let itemCount: Int
    var isDone: Bool
}

struct ErrandRow: View {
    let errand: Errand

    var body: some View {
        HStack {
            Image(systemName: errand.isDone ? "checkmark.circle.fill" : "circle")
            Text(errand.title)
            Spacer()
            Text("\(errand.itemCount) items")
        }
    }
}

struct ErrandBoard: View {
    @State private var errands = [
        Errand(title: "Groceries", itemCount: 12, isDone: false),
        Errand(title: "Pharmacy", itemCount: 1, isDone: true),
        Errand(title: "Hardware store", itemCount: 4, isDone: false),
        Errand(title: "Post office", itemCount: 2, isDone: true)
    ]
    private let visibleLimit = 3

    var body: some View {
        List {
            ForEach(errands.prefix(visibleLimit)) { errand in
                ErrandRow(errand: errand)
            }
            if errands.count > visibleLimit {
                Text("+\(errands.count - visibleLimit) more")
            }
        }
    }
}

