import SwiftUI

struct Errand: Identifiable, Decodable {
    let id: Int
    let title: String
}

@MainActor final class ErrandModel: ObservableObject {
    @Published var errands: [Errand] = []

    func load() async throws {
        let url = URL(string: "https://example.org/errands")!
        let (data, _) = try await URLSession.shared.data(from: url)
        errands = try JSONDecoder().decode([Errand].self, from: data)
    }
}

struct ErrandBoard: View {
    @StateObject private var model = ErrandModel()

    var body: some View {
        List(model.errands) { errand in
            Text(errand.title)
        }
        .task { try? await model.load() }
    }
}

